const text = (msg.payload || '').toString().trim();
const lines = text.split(/\r?\n/);
if (lines.length < 2) {
    node.warn('USGS CSV: sem eventos');
    return null;
}
const header = lines[0];
const ids = [];
const payloads = [];
for (const line of lines.slice(1)) {
    if (!line.trim()) continue;
    // o id e a 12.a coluna e as colunas antes dele nunca tem virgulas nem aspas
    const id = line.split(',')[11];
    if (!id) continue;
    ids.push(id);
    payloads.push(header + '\n' + line);   // mini-CSV: cabecalho + 1 linha
}
msg.rotulo = 'USGS CSV';
msg.n = ids.length;
msg.query = `INSERT INTO raw_sismos (fonte, formato, id_externo, payload)
             SELECT 'USGS-CSV', 'csv', t.id, t.p
             FROM UNNEST($1::text[], $2::text[]) AS t(id, p)
             ON CONFLICT (fonte, id_externo) DO NOTHING`;
msg.params = [ids, payloads];
return msg;

const xml = (msg.payload || '').toString();
const root = xml.match(/<q:quakeml[^>]*>/);
const params = xml.match(/<eventParameters[^>]*>/);
const events = xml.match(/<event\b[\s\S]*?<\/event>/g) || [];
if (!root || !params || !events.length) {
    node.warn('USGS XML: sem eventos');
    return null;
}
const ids = [];
const payloads = [];
for (const ev of events) {
    const m = ev.match(/eventid=([A-Za-z0-9]+)/);
    if (!m) continue;
    ids.push(m[1]);
    // QuakeML valido com 1 evento (mantem os namespaces do original)
    payloads.push('<?xml version="1.0" encoding="UTF-8"?>' + root[0] + params[0] + ev + '</eventParameters></q:quakeml>');
}
msg.rotulo = 'USGS XML';
msg.n = ids.length;
msg.query = `INSERT INTO raw_sismos (fonte, formato, id_externo, payload)
             SELECT 'USGS-XML', 'xml', t.id, t.p
             FROM UNNEST($1::text[], $2::text[]) AS t(id, p)
             ON CONFLICT (fonte, id_externo) DO NOTHING`;
msg.params = [ids, payloads];
return msg;
